class StringIterator {
  private final String s;
  private int pos;
  private char cur = ' ';
  private long remaining;

  public StringIterator(String compressedString) {
    s = compressedString;
  }

  public char next() {
    if (!hasNext()) return ' ';
    if (remaining == 0) {
      cur = s.charAt(pos++);
      long count = 0;
      while (pos < s.length() && Character.isDigit(s.charAt(pos))) count = count * 10 + (s.charAt(pos++) - '0');
      remaining = count;
    }
    remaining--;
    return cur;
  }

  public boolean hasNext() {
    return remaining > 0 || pos < s.length();
  }
}
